fn lookup(table: &[(u16, &'static str)], v: u16) -> Option<&'static str> {
    table.binary_search_by_key(&v, |e| e.0).ok().map(|i| table[i].1)
}

/// Name of a control (a physical key or button).
pub fn control_name(cid: u16) -> String {
    lookup(CONTROLS, cid).map(str::to_string).unwrap_or_else(|| format!("Control {cid:#06x}"))
}

/// Name of a task (what a control does).
pub fn task_name(tid: u16) -> String {
    lookup(TASKS, tid).map(str::to_string).unwrap_or_else(|| format!("Task {tid:#06x}"))
}

pub fn hid_key_name(usage: u16) -> Option<&'static str> {
    lookup(HID_KEYS, usage)
}

pub fn consumer_name(usage: u16) -> Option<&'static str> {
    lookup(CONSUMER_KEYS, usage)
}

pub fn keycode_name(code: u16) -> String {
    lookup(KEYCODES, code).map(str::to_string).unwrap_or_else(|| format!("Key {code}"))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tables_are_sorted_for_lookup() {
        for t in [CONTROLS, TASKS, DISABLE_KEYS, HID_KEYS, CONSUMER_KEYS, MOUSE_BUTTONS, KEYCODES] {
            assert!(t.windows(2).all(|w| w[0].0 < w[1].0));
        }
        assert_eq!(control_name(0x00c3), "Mouse Gesture Button");
        assert_eq!(control_name(0x0052), "Middle Button");
    }
}
